package com.bakeflow.identity;import static com.bakeflow.identity.IdentityDtos.*;import java.util.UUID;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/users") @PreAuthorize("hasAuthority('SCOPE_USER_READ')") public class UserController{private final IdentityService service;public UserController(IdentityService service){this.service=service;}@GetMapping UserPage list(@RequestParam(required=false)String search,@RequestParam(required=false)Boolean active,@RequestParam(required=false)String role,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){return service.users(search,active,role,page,size);}@PostMapping @PreAuthorize("hasAuthority('SCOPE_USER_WRITE')")UserView create(@RequestBody UserInput in){return service.create(in);}@PutMapping("/{id}")@PreAuthorize("hasAuthority('SCOPE_USER_WRITE')")UserView update(@PathVariable UUID id,@RequestBody UserUpdate in){return service.update(id,in);}}
